from collections import deque,defaultdict
R=C=30
lab=[[-1]*C for _ in range(R)]; comps={}; k=0
for i in range(R):
 for j in range(C):
  if a[i][j] and lab[i][j]<0:
   q=deque([(i,j)]); lab[i][j]=k; cells=[]
   while q:
    x,y=q.popleft(); cells.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     xx,yy=x+dx,y+dy
     if 0<=xx<R and 0<=yy<C and a[xx][yy] and lab[xx][yy]<0:
      lab[xx][yy]=k;q.append((xx,yy))
   comps[k]=cells;k+=1
seedcols=defaultdict(list)
for (i,j,v) in [(i,j,a[i][j]) for i in range(R) for j in range(C) if a[i][j]>1]:seedcols[lab[i][j]].append((i,j,v))
[(cid,len(cells),seedcols[cid]) for cid,cells in comps.items() if cid in seedcols],len(comps)

