colored=[]
for i in range(1,29):
 for j in range(1,29):
  cells=[(x,y) for x in range(i-1,i+2) for y in range(j-1,j+2)]
  if all(a[x][y]!=0 for x,y in cells):
   cid=lab[i][j]
   colors=seedcols.get(cid,[])
   if colors:
    color=colors[0][2]
    out[i][j]=color; colored.append((i,j,color))
